use std::{env, fs, path::PathBuf};

fn main() {
    let mpv = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap()).join("vendor").join("mpv");
    let dll = mpv.join("libmpv-2.dll");
    if !dll.exists() || !mpv.join("mpv.lib").exists() {
        panic!("libmpv missing from vendor/mpv: run scripts/get-mpv.ps1 (see README)");
    }
    // libmpv2-sys requires `mpv`; mpv.lib is generated by scripts/get-mpv.ps1
    println!("cargo:rustc-link-search=native={}", mpv.display());
    println!("cargo:rerun-if-changed=vendor/mpv/libmpv-2.dll");

    // OUT_DIR = target/<profile>/build/<crate>[/<hash>]/out: the executable is in target/<profile>
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    let exe_dir = out.ancestors().find(|p| p.ends_with("build")).and_then(|p| p.parent()).unwrap();
    fs::copy(&dll, exe_dir.join("libmpv-2.dll")).expect("copy of libmpv-2.dll");
    // App icon embedded in the exe (logo/StarPlay.ico, regenerated by scripts/make-icon.py)
    println!("cargo:rerun-if-changed=logo/StarPlay.ico");
    embed_resource::compile("starplay.rc", embed_resource::NONE).manifest_optional().unwrap();
    println!("cargo:rerun-if-changed=shaders/glass.glsl");
    fs::copy("shaders/glass.glsl", exe_dir.join("glass.glsl")).expect("copy of glass.glsl");
}
